                    printf("%s ", kS(kK(columnValues)[1])[i]);
                    printf("%lf ", kF(kK(columnValues)[2])[i]);
                    printf("%lld \n", kJ(kK(columnValues)[3])[i]);
                }
            }
            r0(response);
        }
        r0(tableName); 
